using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category → product codes for O(1) category lookup
    private readonly Dictionary<string, List<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    // Parallel array of prices kept in sync for SIMD batch summation
    private readonly List<double> _priceValues = new();
    private readonly Dictionary<string, int> _priceIndexMap = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, decimal price)
    {
        var priceDouble = (double)price;
        _categories[code] = category;
        _prices[code] = priceDouble;

        // Maintain reverse category index
        if (!_categoryIndex.TryGetValue(category, out var list))
        {
            list = new List<string>();
            _categoryIndex[category] = list;
        }
        list.Add(code);

        // Maintain contiguous price array for vectorized summation
        if (_priceIndexMap.TryGetValue(code, out var idx))
        {
            _priceValues[idx] = priceDouble;
        }
        else
        {
            _priceIndexMap[code] = _priceValues.Count;
            _priceValues.Add(priceDouble);
        }
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        if (codes is ICollection<string> coll)
            return SumVectorized(coll);

        // Fallback for arbitrary enumerables
        double total = 0d;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return (decimal)total;
    }

    /// <summary>
    /// Gathers prices into a contiguous buffer then sums with SIMD vectors.
    /// </summary>
    private decimal SumVectorized(ICollection<string> codes)
    {
        var count = codes.Count;
        if (count == 0) return 0m;

        // Gather matching prices into a contiguous span
        var buffer = count <= 256
            ? stackalloc double[count]
            : new double[count];

        int written = 0;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                buffer[written++] = price;
        }

        var span = buffer[..written];
        return (decimal)SumSimd(span);
    }

    private static double SumSimd(ReadOnlySpan<double> values)
    {
        if (values.Length == 0) return 0d;

        var vectors = MemoryMarshal.Cast<double, Vector<double>>(values);
        var vSum = Vector<double>.Zero;

        for (int i = 0; i < vectors.Length; i++)
            vSum += vectors[i];

        double sum = Vector.Sum(vSum);

        // Handle remaining elements beyond the last full vector
        int processed = vectors.Length * Vector<double>.Count;
        for (int i = processed; i < values.Length; i++)
            sum += values[i];

        return sum;
    }

    public List<string> GetProductsByCategory(string category)
    {
        // O(1) lookup via reverse index instead of O(n) scan
        if (_categoryIndex.TryGetValue(category, out var list))
            return new List<string>(list);
        return new List<string>();
    }
}

